const BOX_TOP = -730;

const BOX_HEIGHT = 970;

const UNITS_PER_EM = 1000;

type SetupHeadingProps = {
  /** The step whose heading this draws. */
  step: SetupStep;
  /** How tall the letters stand, which drives the width with them. */
  size?: number;
};

/** The heading a setup step opens with, set in the face the brand uses for its own words. */
export function SetupHeading({ step, size = 28 }: SetupHeadingProps) {
  const heading = HEADINGS[step];

  if (heading === undefined) {
    return null;
  }

  return (
    <svg
      aria-label={heading.reads}
      className="text-ink"
      height={(BOX_HEIGHT / UNITS_PER_EM) * size}
      role="img"
      viewBox={`0 ${String(BOX_TOP)} ${String(heading.advance)} ${String(BOX_HEIGHT)}`}
      width={(heading.advance / UNITS_PER_EM) * size}
    >
      <path d={heading.drawn} fill="currentColor" />
    </svg>
  );
}
